 ('authority_metadata_preflight_v5(text,text,boolean,text,jsonb)','3330f09d5851cd747af8d09409250f32ba9cc5478f69a703c93b80f11557b067','2157d1086670ee38d5766cf2c4ee28d37bf8dbb965af012bc7a681c7999cbefe',$pairs$[[" OR p_id IS NULL OR p_id='' OR p_rename IS NULL OR p_audit IS NULL OR p_audit='' OR length(p_audit)>64 THEN\n  RAISE EXCEPTION 'metadata preflight requires full resource decision entry' USING ERRCODE='42501';\n END IF;\n IF p_kind IS NULL OR p_kind NOT IN ('account','project') THEN\n  RAISE EXCEPTION 'metadata v5 requires account/project label change' USING ERRCODE='22023';END IF;\n CASE p_kind WHEN 'account' THEN table_name:='accounts';\n WHEN 'project' THEN table_name:='projects';\n ELSE RAISE EXCEPTION 'unsupported metadata update' USING ERRCODE='22023'; END CASE;\n -- Вход уже удерживает полный набор account fences. Для project/service_account\n -- UNIQUE(account_id,name) не допускает конкурента того же ключа без того же\n", " OR p_id IS NULL OR p_id='' OR p_rename IS NULL OR p_audit IS NULL OR p_audit='' OR length(p_audit)>64 THEN\n  RAISE EXCEPTION 'metadata preflight requires full resource decision entry' USING ERRCODE='42501';\n END IF;\n IF p_kind IS NULL OR p_kind NOT IN ('account','project','service_account') THEN\n  RAISE EXCEPTION 'metadata v5 requires supported resource label change' USING ERRCODE='22023';END IF;\n CASE p_kind WHEN 'account' THEN table_name:='accounts';\n WHEN 'project' THEN table_name:='projects';\n WHEN 'service_account' THEN table_name:='service_accounts';\n ELSE RAISE EXCEPTION 'unsupported metadata update' USING ERRCODE='22023'; END CASE;\n -- Вход уже удерживает полный набор account fences. Для project/service_account\n -- UNIQUE(account_id,name) не допускает конкурента того же ключа без того же\n"]]$pairs$::jsonb),
 ('authority_metadata_preflight_staged_v1(text,text,boolean,text,jsonb)','bb865b5cedc10413092150e22edd804c9d18cf9ac9dd7180a5ce20d12245b032','2b7eb7bbe734d51412f01b37380a841512d2a74890c277d21990f7f39f14eb45',$pairs$[[" -- Сначала корень, затем owning account: позднего повышения lock нет.\n -- Только реальная смена меток account/project удерживает полный census,\n -- включая отсутствие кандидатов. Классификация берётся из locked OLD.\n IF p_kind IN ('account','project') AND p_patch ? 'labels'\n AND p_patch->'labels' IS DISTINCT FROM row_value->'labels' THEN\n  PERFORM scope FROM kaname.authority_binding_epoch WHERE scope='' FOR SHARE;\n ELSE\n", " -- Сначала корень, затем owning account: позднего повышения lock нет.\n -- Только реальная смена меток account/project удерживает полный census,\n -- включая отсутствие кандидатов. Классификация берётся из locked OLD.\n IF p_kind IN ('account','project','service_account') AND p_patch ? 'labels'\n AND p_patch->'labels' IS DISTINCT FROM row_value->'labels' THEN\n  PERFORM scope FROM kaname.authority_binding_epoch WHERE scope='' FOR SHARE;\n ELSE\n"]]$pairs$::jsonb),
 ('access_labels_immutable_v1()','78051349c7cec4e3c5df8cdd8e11bc36243d9ad8d0c227fde363babfeaa258d9','9d3a52a7920a1f0532c932c31de06f4a8f19e39c5ef1375b0b3bebe603b65992',$pairs$[[" END IF;\n IF NEW.access_labels IS NOT DISTINCT FROM OLD.access_labels THEN RETURN NEW;END IF;\n SELECT c.relowner INTO STRICT owner_oid FROM pg_catalog.pg_class c WHERE c.oid='kaname.authority_writer_protocol'::regclass;\n IF TG_TABLE_NAME NOT IN ('accounts','projects')\n  OR owner_oid IS DISTINCT FROM (SELECT r.oid FROM pg_catalog.pg_roles r WHERE r.rolname=current_user) THEN\n  RAISE EXCEPTION 'access label mutation requires a protected writer' USING ERRCODE='42501';END IF;\n command:=kaname._authority_metadata_access_label_origin_v1(TG_TABLE_NAME,OLD.id);\n", " END IF;\n IF NEW.access_labels IS NOT DISTINCT FROM OLD.access_labels THEN RETURN NEW;END IF;\n SELECT c.relowner INTO STRICT owner_oid FROM pg_catalog.pg_class c WHERE c.oid='kaname.authority_writer_protocol'::regclass;\n IF TG_TABLE_NAME NOT IN ('accounts','projects','service_accounts')\n  OR owner_oid IS DISTINCT FROM (SELECT r.oid FROM pg_catalog.pg_roles r WHERE r.rolname=current_user) THEN\n  RAISE EXCEPTION 'access label mutation requires a protected writer' USING ERRCODE='42501';END IF;\n command:=kaname._authority_metadata_access_label_origin_v1(TG_TABLE_NAME,OLD.id);\n"]]$pairs$::jsonb),
 ('authority_access_label_storage_valid_v1()','a24dc7f2ffbb450fb0229aa05a3af307a831a106d673fa34f35424644f77016f','a7821d7f58ee98dc10277fb53d2f588763b27e2dbdb4476d361f6474439e1055',$pairs$[[" IF owner_oid IS DISTINCT FROM (SELECT oid FROM pg_roles WHERE rolname=current_user) THEN RETURN false;END IF;\n FOR expected IN SELECT * FROM (VALUES\n ('access_labels_valid_v1(jsonb)','5bdcbf012ab0dee0838575bc22c3109d97483e1caf2f5543d810f46be03f9c60',false,'i'),\n ('access_labels_immutable_v1()','78051349c7cec4e3c5df8cdd8e11bc36243d9ad8d0c227fde363babfeaa258d9',false,'v')\n ) p(signature,digest,definer,volatility) LOOP\n  IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('kaname.'||expected.signature)\n   AND p.proowner=owner_oid AND p.prosecdef=expected.definer AND p.provolatile::text=expected.volatility\n", " IF owner_oid IS DISTINCT FROM (SELECT oid FROM pg_roles WHERE rolname=current_user) THEN RETURN false;END IF;\n FOR expected IN SELECT * FROM (VALUES\n ('access_labels_valid_v1(jsonb)','5bdcbf012ab0dee0838575bc22c3109d97483e1caf2f5543d810f46be03f9c60',false,'i'),\n ('access_labels_immutable_v1()','9d3a52a7920a1f0532c932c31de06f4a8f19e39c5ef1375b0b3bebe603b65992',false,'v')\n ) p(signature,digest,definer,volatility) LOOP\n  IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('kaname.'||expected.signature)\n   AND p.proowner=owner_oid AND p.prosecdef=expected.definer AND p.provolatile::text=expected.volatility\n"]]$pairs$::jsonb),
 ('_authority_resource_access_label_requirements_v1(text,jsonb,jsonb,integer,integer)','fed3aeef3a1236cfba09551e3e77edfc7450c4213e9b4f8eed2faab698195e9d','978758f5cd292059a16258ec393df4768aa3fc5bb0e26fffd5d6b0248e4134db',$pairs$[["\nDECLARE\n resource_id text;\n account_id text;\n old_labels jsonb;\n new_labels jsonb;\n", "\nDECLARE\n resource_id text;\n resource_name text;\n account_id text;\n old_labels jsonb;\n new_labels jsonb;\n"], [" IF current_setting('transaction_isolation')<>'read committed' THEN\n  RAISE EXCEPTION 'access label definitions require a locked decision transaction' USING ERRCODE='25001';\n END IF;\n IF p_resource IS NULL OR p_resource NOT IN ('account','project')\n  OR jsonb_typeof(p_old) IS DISTINCT FROM 'object'\n  OR jsonb_typeof(p_new) IS DISTINCT FROM 'object'\n  OR jsonb_typeof(p_old->'id') IS DISTINCT FROM 'string'\n  OR p_old->'id' IS DISTINCT FROM p_new->'id'\n  OR (p_resource='project' AND (\n   jsonb_typeof(p_old->'account_id') IS DISTINCT FROM 'string'\n   OR p_old->'account_id' IS DISTINCT FROM p_new->'account_id')) THEN\n  RAISE EXCEPTION 'invalid resource access label identity' USING ERRCODE='42501';\n END IF;\n resource_id:=p_old->>'id';\n account_id:=CASE WHEN p_resource='account' THEN resource_id ELSE p_old->>'account_id' END;\n old_labels:=p_old->'access_labels';\n new_labels:=p_new->'access_labels';\n IF account_id COLLATE \"C\" !~ '^acc[a-zA-Z0-9_-]{1,61}$'\n  OR (p_resource='project' AND resource_id COLLATE \"C\" !~ '^prj[a-zA-Z0-9_-]{1,61}$')\n  OR kaname.access_labels_valid_v1(old_labels) IS DISTINCT FROM true\n  OR kaname.access_labels_valid_v1(new_labels) IS DISTINCT FROM true THEN\n  RAISE EXCEPTION 'invalid resource access label images' USING ERRCODE='42501';\n", " IF current_setting('transaction_isolation')<>'read committed' THEN\n  RAISE EXCEPTION 'access label definitions require a locked decision transaction' USING ERRCODE='25001';\n END IF;\n IF p_resource IS NULL OR p_resource NOT IN ('account','project','service_account')\n  OR jsonb_typeof(p_old) IS DISTINCT FROM 'object'\n  OR jsonb_typeof(p_new) IS DISTINCT FROM 'object'\n  OR jsonb_typeof(p_old->'id') IS DISTINCT FROM 'string'\n  OR p_old->'id' IS DISTINCT FROM p_new->'id'\n  OR (p_resource IN ('project','service_account') AND (\n   jsonb_typeof(p_old->'account_id') IS DISTINCT FROM 'string'\n   OR p_old->'account_id' IS DISTINCT FROM p_new->'account_id')) THEN\n  RAISE EXCEPTION 'invalid resource access label identity' USING ERRCODE='42501';\n END IF;\n resource_id:=p_old->>'id';\n resource_name:=CASE p_resource WHEN 'service_account' THEN 'serviceAccount' ELSE p_resource END;\n account_id:=CASE WHEN p_resource='account' THEN resource_id ELSE p_old->>'account_id' END;\n old_labels:=p_old->'access_labels';\n new_labels:=p_new->'access_labels';\n IF account_id COLLATE \"C\" !~ '^acc[a-zA-Z0-9_-]{1,61}$'\n  OR (p_resource='project' AND resource_id COLLATE \"C\" !~ '^prj[a-zA-Z0-9_-]{1,61}$')\n  OR (p_resource='service_account' AND resource_id COLLATE \"C\" !~ '^sva[a-zA-Z0-9_-]{1,61}$')\n  OR kaname.access_labels_valid_v1(old_labels) IS DISTINCT FROM true\n  OR kaname.access_labels_valid_v1(new_labels) IS DISTINCT FROM true THEN\n  RAISE EXCEPTION 'invalid resource access label images' USING ERRCODE='42501';\n"], ["   FROM (VALUES ('cluster','cluster_root'),('account',account_id),\n    ('project',CASE WHEN p_resource='project' THEN resource_id END)) s(kind,id)\n   JOIN kaname.authority_access_label_definition d ON d.scope_kind=s.kind AND d.scope_id=s.id\n    AND d.module='iam' AND d.resource=p_resource AND d.label_key=delta.changed_key\n   ORDER BY d.id LIMIT 2\n  LOOP\n   candidates:=candidates+1;\n", "   FROM (VALUES ('cluster','cluster_root'),('account',account_id),\n    ('project',CASE WHEN p_resource='project' THEN resource_id END)) s(kind,id)\n   JOIN kaname.authority_access_label_definition d ON d.scope_kind=s.kind AND d.scope_id=s.id\n    AND d.module='iam' AND d.resource=resource_name AND d.label_key=delta.changed_key\n   ORDER BY d.id LIMIT 2\n  LOOP\n   candidates:=candidates+1;\n"], ["    RAISE EXCEPTION 'resource access label definition is ambiguous' USING ERRCODE='42501';\n   END IF;\n   IF kaname.authority_access_label_definition_hold_v1(held.scope_kind,held.scope_id,'iam',\n       p_resource,delta.changed_key,held.id,held.revision,held.row_xmin,held.row_ctid,delta.new_value) IS DISTINCT FROM true THEN\n    RAISE EXCEPTION 'resource access label value or generation is not allowed' USING ERRCODE='42501';\n   END IF;\n   result:=result||jsonb_build_array(jsonb_build_object('key',delta.changed_key,\n", "    RAISE EXCEPTION 'resource access label definition is ambiguous' USING ERRCODE='42501';\n   END IF;\n   IF kaname.authority_access_label_definition_hold_v1(held.scope_kind,held.scope_id,'iam',\n       resource_name,delta.changed_key,held.id,held.revision,held.row_xmin,held.row_ctid,delta.new_value) IS DISTINCT FROM true THEN\n    RAISE EXCEPTION 'resource access label value or generation is not allowed' USING ERRCODE='42501';\n   END IF;\n   result:=result||jsonb_build_array(jsonb_build_object('key',delta.changed_key,\n"]]$pairs$::jsonb),
 ('_authority_access_label_freshness_storage_v1()','698216e4db290dfaea7145f875e9d83c06322627d8b2a5ce44621731579ad2b4','45464597290417cfad0f087b8ccf44453c7b4362b94bde2229fe3e0e785b33f5',$pairs$[[" ) THEN RETURN false;END IF;\n IF EXISTS(SELECT 1 FROM (VALUES\n  ('authority_access_label_dirty_root','authority_access_label_dirty_root_type',\n   'root_type=ANYARRAY[''iam.account''::text,''iam.project''::text]'),\n  ('authority_access_label_dirty_root','authority_access_label_dirty_root_id','root_id<>''''::text'),\n  ('authority_access_label_dirty_root','authority_access_label_dirty_root_labels','kaname.access_labels_valid_v1new_labels'),\n  ('authority_access_label_dirty_fact','authority_access_label_dirty_fact_type','object_type<>''''::textANDobject_type!~~''%.%''::text'),\n", " ) THEN RETURN false;END IF;\n IF EXISTS(SELECT 1 FROM (VALUES\n  ('authority_access_label_dirty_root','authority_access_label_dirty_root_type',\n   'root_type=ANYARRAY[''iam.account''::text,''iam.project''::text,''iam.serviceAccount''::text]'),\n  ('authority_access_label_dirty_root','authority_access_label_dirty_root_id','root_id<>''''::text'),\n  ('authority_access_label_dirty_root','authority_access_label_dirty_root_labels','kaname.access_labels_valid_v1new_labels'),\n  ('authority_access_label_dirty_fact','authority_access_label_dirty_fact_type','object_type<>''''::textANDobject_type!~~''%.%''::text'),\n"]]$pairs$::jsonb),
 ('_authority_metadata_access_label_origin_v1(text,text)','c44e76add35923e06780067d14e936764fe3262bbfb277eb499ad1260bccc39c','78cdfb6dc5414d9be886d392dc15520155b273407e52463b08e6f430c2c9f0ad',$pairs$[[" freshness jsonb;\nBEGIN\n PERFORM kaname.authority_protocol_require_owner();\n IF p_table IS NULL OR p_table NOT IN ('accounts','projects') OR coalesce(p_id,'')='' THEN\n  RAISE EXCEPTION 'protected metadata resource coordinate is invalid' USING ERRCODE='42501';END IF;\n SELECT x.proof,x.header INTO STRICT proof,header FROM kaname._authority_sequence_probe_v3() x;\n IF proof IS NULL OR proof->>'kind' IS DISTINCT FROM 'resource'\n", " freshness jsonb;\nBEGIN\n PERFORM kaname.authority_protocol_require_owner();\n IF p_table IS NULL OR p_table NOT IN ('accounts','projects','service_accounts') OR coalesce(p_id,'')='' THEN\n  RAISE EXCEPTION 'protected metadata resource coordinate is invalid' USING ERRCODE='42501';END IF;\n SELECT x.proof,x.header INTO STRICT proof,header FROM kaname._authority_sequence_probe_v3() x;\n IF proof IS NULL OR proof->>'kind' IS DISTINCT FROM 'resource'\n"], ["  OR jsonb_typeof(freshness) IS DISTINCT FROM 'object'\n  OR jsonb_typeof(freshness->'facts') IS DISTINCT FROM 'array'\n  OR freshness->>'root_id' IS DISTINCT FROM p_id\n  OR freshness->>'root_type' IS DISTINCT FROM (CASE p_table WHEN 'accounts' THEN 'iam.account' ELSE 'iam.project' END) THEN\n  RAISE EXCEPTION 'protected metadata apply or freshness receipt is missing' USING ERRCODE='42501';END IF;\n SELECT e.origin INTO command FROM pg_temp.kaname_authority_sequence_effects e\n WHERE e.nonce=(header->>'nonce')::uuid AND e.ordinal=1 AND e.table_name='resource_journal' AND e.selected\n", "  OR jsonb_typeof(freshness) IS DISTINCT FROM 'object'\n  OR jsonb_typeof(freshness->'facts') IS DISTINCT FROM 'array'\n  OR freshness->>'root_id' IS DISTINCT FROM p_id\n  OR freshness->>'root_type' IS DISTINCT FROM (CASE p_table WHEN 'accounts' THEN 'iam.account' WHEN 'projects' THEN 'iam.project' WHEN 'service_accounts' THEN 'iam.serviceAccount' END) THEN\n  RAISE EXCEPTION 'protected metadata apply or freshness receipt is missing' USING ERRCODE='42501';END IF;\n SELECT e.origin INTO command FROM pg_temp.kaname_authority_sequence_effects e\n WHERE e.nonce=(header->>'nonce')::uuid AND e.ordinal=1 AND e.table_name='resource_journal' AND e.selected\n"]]$pairs$::jsonb),
 ('_authority_metadata_access_label_carry_v1(text,text,jsonb,integer,integer)','9d099e8fb586eaca406c87cc4d1bf2e0fe91ebec8ecbbaff8e7e307978c29b9e','0c3a3bf0b6f329da989508ee996659557a419ca12e3c83eab11ae0daf5e126b7',$pairs$[["DECLARE previous_generation uuid;previous_labels jsonb;facts jsonb;n integer;\nBEGIN\n PERFORM kaname.authority_protocol_require_owner();\n IF coalesce(p_root_type,'') NOT IN ('iam.account','iam.project') OR coalesce(p_root_id,'')=''\n  OR kaname.access_labels_valid_v1(p_old_labels) IS DISTINCT FROM true\n  OR p_rows IS NULL OR p_rows NOT BETWEEN 1 AND 100000 OR p_reads IS NULL OR p_reads NOT BETWEEN 1 AND 4096 THEN\n  RAISE EXCEPTION 'invalid access label freshness carry' USING ERRCODE='42501';END IF;\n", "DECLARE previous_generation uuid;previous_labels jsonb;facts jsonb;n integer;\nBEGIN\n PERFORM kaname.authority_protocol_require_owner();\n IF coalesce(p_root_type,'') NOT IN ('iam.account','iam.project','iam.serviceAccount') OR coalesce(p_root_id,'')=''\n  OR kaname.access_labels_valid_v1(p_old_labels) IS DISTINCT FROM true\n  OR p_rows IS NULL OR p_rows NOT BETWEEN 1 AND 100000 OR p_reads IS NULL OR p_reads NOT BETWEEN 1 AND 4096 THEN\n  RAISE EXCEPTION 'invalid access label freshness carry' USING ERRCODE='42501';END IF;\n"]]$pairs$::jsonb),
 ('_authority_metadata_access_label_freshness_v1()','c51c9eeb9de625b8282b552c6f92be83793e9c037d97c8e767c6830e64bb8347','d3f11fdcbc31b583098c4ddec750fdd4dd4f31b60de169a0d355df7ab75857b8',$pairs$[[" affected integer;\nBEGIN\n PERFORM kaname.authority_protocol_require_owner();\n IF TG_TABLE_SCHEMA<>'kaname' OR TG_TABLE_NAME NOT IN ('accounts','projects')\n  OR TG_WHEN<>'AFTER' OR TG_LEVEL<>'ROW' OR TG_OP<>'UPDATE'\n  OR NEW.access_labels IS NOT DISTINCT FROM OLD.access_labels THEN\n  RAISE EXCEPTION 'invalid access label freshness trigger context' USING ERRCODE='42501';END IF;\n", " affected integer;\nBEGIN\n PERFORM kaname.authority_protocol_require_owner();\n IF TG_TABLE_SCHEMA<>'kaname' OR TG_TABLE_NAME NOT IN ('accounts','projects','service_accounts')\n  OR TG_WHEN<>'AFTER' OR TG_LEVEL<>'ROW' OR TG_OP<>'UPDATE'\n  OR NEW.access_labels IS NOT DISTINCT FROM OLD.access_labels THEN\n  RAISE EXCEPTION 'invalid access label freshness trigger context' USING ERRCODE='42501';END IF;\n"]]$pairs$::jsonb),
 ('_authority_access_label_object_generation_capture_v1(text,text,integer,integer)','2d9e55e217c4435813bafca1a2af29623a08ceb13ae69b630d9aae4d973e9eb2','e963c3d068d0baa9685d1d70b4f0c362a8cb834653687a3aa694ba06679f9823',$pairs$[[" -- Координата факта использует model type, как индекс dirty_fact_coordinate.\n -- Прямой корень проверяется независимо от наличия accounts/projects и фактов:\n -- пустое поколение удалённого ресурса тоже должно попасть в снимок.\n direct_type:=CASE p_model WHEN 'account' THEN 'iam.account' WHEN 'project' THEN 'iam.project' END;\n IF direct_type IS NOT NULL THEN\n  direct_root:=jsonb_build_object('root_type',direct_type,'root_id',p_id,'state',NULL);\n END IF;\n", " -- Координата факта использует model type, как индекс dirty_fact_coordinate.\n -- Прямой корень проверяется независимо от наличия accounts/projects и фактов:\n -- пустое поколение удалённого ресурса тоже должно попасть в снимок.\n direct_type:=CASE p_model WHEN 'account' THEN 'iam.account' WHEN 'project' THEN 'iam.project' WHEN 'iam_service_account' THEN 'iam.serviceAccount' END;\n IF direct_type IS NOT NULL THEN\n  direct_root:=jsonb_build_object('root_type',direct_type,'root_id',p_id,'state',NULL);\n END IF;\n"]]$pairs$::jsonb),
 ('authority_resource_reconcile_pending_v1(text,text,integer,integer)','e635320344ae43c43f4f213f37064b423a905c56b156512f4fa925c12a1e218b','80ff9887f485df5264ab9e5fe596296624e5fee954620415d7d1cf032e1969dc',$pairs$[[" -- Работник может обнаружить большое открытое поколение с постоянным\n -- бюджетом: ждём завершения поколения без чтения полного списка фактов.\n logical_reads:=1;\n direct_type:=CASE p_model WHEN 'account' THEN 'iam.account' WHEN 'project' THEN 'iam.project' END;\n IF direct_type IS NOT NULL THEN\n  SELECT EXISTS(SELECT 1 FROM kaname.authority_access_label_dirty_root r\n   WHERE r.root_type=direct_type AND r.root_id=p_id) INTO pending;\n", " -- Работник может обнаружить большое открытое поколение с постоянным\n -- бюджетом: ждём завершения поколения без чтения полного списка фактов.\n logical_reads:=1;\n direct_type:=CASE p_model WHEN 'account' THEN 'iam.account' WHEN 'project' THEN 'iam.project' WHEN 'iam_service_account' THEN 'iam.serviceAccount' END;\n IF direct_type IS NOT NULL THEN\n  SELECT EXISTS(SELECT 1 FROM kaname.authority_access_label_dirty_root r\n   WHERE r.root_type=direct_type AND r.root_id=p_id) INTO pending;\n"]]$pairs$::jsonb),
 ('_authority_access_label_generation_root_keys_v1(jsonb)','cf3e2c08b2f44e84d1f69a1cfd791ad4ab48b3e46cc4cf870e6294007c3cb620','1f982cdaa85d2f14a867b0388bfd31be71b1ec757315a8df6c672604441bd3f0',$pairs$[["  OR jsonb_typeof(coordinate->1) IS DISTINCT FROM 'string' THEN\n   RAISE EXCEPTION 'generation root coordinate malformed' USING ERRCODE='42501';END IF;\n  typ:=coordinate->>0;identifier:=coordinate->>1;\n  IF typ NOT IN ('iam.account','iam.project') OR identifier=''\n  OR octet_length(identifier)>16384 OR identifier ~ '[:#*[:space:][:cntrl:]]' THEN\n   RAISE EXCEPTION 'generation root coordinate invalid' USING ERRCODE='42501';END IF;\n END LOOP;\n", "  OR jsonb_typeof(coordinate->1) IS DISTINCT FROM 'string' THEN\n   RAISE EXCEPTION 'generation root coordinate malformed' USING ERRCODE='42501';END IF;\n  typ:=coordinate->>0;identifier:=coordinate->>1;\n  IF typ NOT IN ('iam.account','iam.project','iam.serviceAccount') OR identifier=''\n  OR octet_length(identifier)>16384 OR identifier ~ '[:#*[:space:][:cntrl:]]' THEN\n   RAISE EXCEPTION 'generation root coordinate invalid' USING ERRCODE='42501';END IF;\n END LOOP;\n"]]$pairs$::jsonb),
