CREATE FUNCTION kaname.authority_metadata_service_account_access_label_ready_v1()
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $ready$
DECLARE owner_oid oid;invoker oid;fn oid;item record;bundle record;catalog_payload jsonb;
BEGIN
 SELECT relowner INTO owner_oid FROM pg_catalog.pg_class WHERE oid='kaname.authority_writer_protocol'::regclass;
 SELECT oid INTO invoker FROM pg_catalog.pg_roles WHERE rolname=coalesce(nullif(current_setting('role'),'none'),session_user);
 IF owner_oid IS DISTINCT FROM current_user::regrole::oid OR invoker IS NULL
  OR kaname._authority_metadata_access_label_runtime_cohort_v2(invoker) IS DISTINCT FROM true
  OR kaname.authority_metadata_access_label_ready_v2('metadata-access-label/owner-retention-v2') IS DISTINCT FROM true
  OR kaname._authority_access_label_freshness_storage_v1() IS DISTINCT FROM true THEN RETURN false;END IF;
 -- Это точная установленная генерация всех расширенных closures, а не имя API.
 FOR item IN SELECT * FROM (VALUES
  ('authority_protocol_row_guard()','6f7973209b9f2dd87e2734a257d8215054b68a3efd404bb67a2fe59188a0d251'),
  ('authority_metadata_preflight_v4(text,text,boolean,text,jsonb)','2bf3a9aba846a188574bbeb19ac090534236cfa4dd2753be1017991a196be1a2'),
  ('_authority_crud_storage_v3()','1ec552fc5336a98cece075fa2d69e3cd78807ab57865e1ad1a499142512dce9f'),
  ('_authority_full_contract_storage_v3()','2822204d78946d3a74f9d8a1d498c2b64e8571da479d6280bf8dc1e63559d966'),
  ('authority_metadata_preflight_v5(text,text,boolean,text,jsonb)','2157d1086670ee38d5766cf2c4ee28d37bf8dbb965af012bc7a681c7999cbefe'),
  ('authority_metadata_preflight_staged_v1(text,text,boolean,text,jsonb)','2b7eb7bbe734d51412f01b37380a841512d2a74890c277d21990f7f39f14eb45'),
  ('access_labels_immutable_v1()','9d3a52a7920a1f0532c932c31de06f4a8f19e39c5ef1375b0b3bebe603b65992'),
  ('authority_access_label_storage_valid_v1()','a7821d7f58ee98dc10277fb53d2f588763b27e2dbdb4476d361f6474439e1055'),
  ('_authority_resource_access_label_requirements_v1(text,jsonb,jsonb,integer,integer)','978758f5cd292059a16258ec393df4768aa3fc5bb0e26fffd5d6b0248e4134db'),
  ('_authority_access_label_freshness_storage_v1()','45464597290417cfad0f087b8ccf44453c7b4362b94bde2229fe3e0e785b33f5'),
  ('_authority_metadata_access_label_origin_v1(text,text)','78cdfb6dc5414d9be886d392dc15520155b273407e52463b08e6f430c2c9f0ad'),
  ('_authority_metadata_access_label_carry_v1(text,text,jsonb,integer,integer)','0c3a3bf0b6f329da989508ee996659557a419ca12e3c83eab11ae0daf5e126b7'),
  ('_authority_metadata_access_label_freshness_v1()','d3f11fdcbc31b583098c4ddec750fdd4dd4f31b60de169a0d355df7ab75857b8'),
  ('_authority_access_label_object_generation_capture_v1(text,text,integer,integer)','e963c3d068d0baa9685d1d70b4f0c362a8cb834653687a3aa694ba06679f9823'),
  ('authority_resource_reconcile_pending_v1(text,text,integer,integer)','80ff9887f485df5264ab9e5fe596296624e5fee954620415d7d1cf032e1969dc'),
  ('_authority_access_label_generation_root_keys_v1(jsonb)','1f982cdaa85d2f14a867b0388bfd31be71b1ec757315a8df6c672604441bd3f0'),
  ('_authority_access_label_object_generation_finish_v1(jsonb,jsonb,integer,integer)','836ee3bddf4e49cf71ab918648cddd724d6c7146173ba06457fd5f6f53efb7c4'),
  ('_authority_access_label_generation_discharge_v1(jsonb,jsonb,jsonb,jsonb,timestamptz,integer)','753a8da9eb64f88c4adc7e6969eeb15eca68170defc3df7ebe914b0fcc8f5f9f'),
  ('authority_metadata_access_label_write_v1(text,text)','ae74cbba1d0dd325a425a7854bf0bee64f72bc711f7dcdbaec9953ace842e1f7'),
  ('_authority_metadata_access_label_carrier_census_v1(text,jsonb,jsonb,integer,integer,integer)','96cd1f25c20b292affd41eea5c871cefb585bf232d5385c2c1f3bd67dad7bac8'),
  ('_authority_metadata_access_label_prefinal_carriers_v1(text,text,text,jsonb,jsonb,integer,integer,integer)','4ee4541d07e9e609445d477a23163a82b297be0bb8588698d4aec8930ae77860'),
  ('_authority_metadata_access_label_early_walk_v1(jsonb,text,text,integer,integer,integer)','b6874b32493ddb7bf8bfe4e70afa10ebb0acb2c8ebf0792419c77969a40d6475'),
  ('_authority_metadata_access_label_early_closure_v1(jsonb,jsonb,integer,integer,integer)','aa7e8d053574b69892a5f61f54099f9c6c8718554f47a97eee838d5670ffafeb'),
  ('_authority_metadata_access_label_held_replay_v1(jsonb,jsonb,jsonb,integer,integer,integer)','711c129d2eb1f9e60d9cefc2136a58b9487e3926649f47ed85087fa423e34f31'),
  ('_authority_metadata_access_label_hold_and_replay_v1(jsonb,boolean,integer,integer,integer)','8322223a45741ef4a169d62b03e8e827baa6bf276af10bc60e330c365ff040e1'),
  ('_authority_access_label_member_partition_v1(text,text,text[],jsonb,jsonb,jsonb,integer,integer)','f4367d9db5c32b4da4d5a364a244aa7d7e1437a50d9cc4622e69a7a89f03ec26'),
  ('_authority_access_label_old_facts_v2(text,text,text[],jsonb,jsonb,jsonb,integer,integer)','33d20a2c1b37c3edee7949d1df8390bf2f26c31d4cd65ecc82c8dd4e1aa5ffa5'),
  ('_authority_metadata_access_label_retention_plan_v1(jsonb,jsonb,jsonb,jsonb,text,jsonb,jsonb,integer)','5afba290c6900e52f68700275d833d3f1af86d856f21d8f43fa7bf19892cc586'),
  ('_authority_metadata_access_label_compile_reserve_v1(jsonb,text,text,text,integer,integer,integer)','5b99413fb55cfcab7302e560b12fc68b286a52ae4534b905893f623f0de2c763'),
  ('_authority_metadata_access_label_retention_accept_v1(text,text,integer,integer,integer)','9e15fcfed80830c65b5a91c7fbd3629433a9c8c962579328bee3e3b5e7e66565'),
  ('authority_metadata_access_label_ready_v2(text)','86d73a4052674f53f8bc1616750878aefa0d14b521d5f1c9c73e5acfd52f1d35'),
  ('_authority_metadata_access_label_grant_v2(regrole)','022fda6877e5f9beffef89fcc0bae8da3cdb8dba1b4b1c362747c35af8556cb5')
 ) expected(signature,digest) LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_proc p WHERE p.oid=to_regprocedure('kaname.'||item.signature)
   AND p.proowner=owner_oid AND encode(sha256(convert_to(p.prosrc,'UTF8')),'hex')=item.digest) THEN RETURN false;END IF;
 END LOOP;
 IF NOT has_table_privilege(invoker,'kaname.service_accounts','SELECT')
  OR EXISTS(SELECT 1 FROM unnest(ARRAY['name','description','labels','access_labels']) field
    WHERE NOT has_column_privilege(invoker,'kaname.service_accounts',field,'UPDATE'))
  OR EXISTS(SELECT 1 FROM pg_catalog.pg_class c WHERE c.oid='kaname.service_accounts'::regclass
    AND (c.relkind<>'r' OR c.relrowsecurity OR c.relforcerowsecurity OR c.relispartition OR c.relhassubclass OR c.relhasrules))
  OR EXISTS(SELECT 1 FROM (VALUES ('id','text'),('account_id','text'),('created_by_type','text'),('created_by_id','text'),('access_labels','jsonb')) e(name,typ)
   LEFT JOIN pg_catalog.pg_attribute a ON a.attrelid='kaname.service_accounts'::regclass AND a.attname=e.name
   WHERE a.attnum IS NULL OR a.attisdropped OR a.atttypid<>to_regtype(e.typ)) THEN RETURN false;END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_trigger t
  WHERE t.tgrelid='kaname.service_accounts'::regclass AND t.tgname='access_labels_000_commit_freshness'
   AND t.tgfoid='kaname._authority_metadata_access_label_freshness_v1()'::regprocedure
   AND t.tgtype=17 AND t.tgenabled='O' AND NOT t.tgisinternal AND t.tgnargs=0 AND t.tgattr=''::int2vector
   AND t.tgconstraint=0 AND NOT t.tgdeferrable AND NOT t.tginitdeferred
   AND pg_get_triggerdef(t.oid) LIKE '% WHEN ((old.access_labels IS DISTINCT FROM new.access_labels)) EXECUTE FUNCTION %') THEN RETURN false;END IF;
 SELECT * INTO bundle FROM kaname.authority_protocol_read_bundle();
 catalog_payload:=convert_from(bundle.catalog_json,'UTF8')::jsonb;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(catalog_payload#>'{Live,Resources}') r
  WHERE r->>'Module'='iam' AND r->>'Resource'='serviceAccount' AND r->>'ObjectType'='iam_service_account')
 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(catalog_payload#>'{Live,Verbs}') v
  WHERE v->>'Module'='iam' AND v->>'Resource'='serviceAccount' AND v->>'Verb'='update')
 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(catalog_payload#>'{Live,Verbs}') v
  WHERE v->>'Module'='iam' AND v->>'Resource'='accessLabel' AND v->>'Verb'='apply') THEN RETURN false;END IF;
 fn:='kaname.authority_metadata_service_account_access_label_ready_v1()'::regprocedure;
 IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_proc p WHERE p.oid=fn AND p.proowner=owner_oid
  AND p.prosecdef AND p.provolatile='s' AND p.prorettype='boolean'::regtype
  AND NOT(p.proretset OR p.proisstrict OR p.proleakproof) AND p.proparallel='u'
  AND p.proconfig=ARRAY['search_path=pg_catalog, pg_temp']::text[]
  AND p.pronargs=0 AND p.pronargdefaults=0 AND p.provariadic=0
  AND has_function_privilege(invoker,p.oid,'EXECUTE')
  AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a
   WHERE a.grantee<>owner_oid AND (a.grantee=0 OR a.is_grantable OR a.privilege_type<>'EXECUTE'
    OR kaname._authority_metadata_access_label_runtime_cohort_v2(a.grantee) IS DISTINCT FROM true))) THEN RETURN false;END IF;
 RETURN true;
END;
$ready$;
