CREATE TRIGGER access_labels_000_commit_freshness AFTER UPDATE ON kaname.service_accounts
FOR EACH ROW WHEN (OLD.access_labels IS DISTINCT FROM NEW.access_labels)
EXECUTE FUNCTION kaname._authority_metadata_access_label_freshness_v1();
-- +goose StatementBegin
DO $acl$
DECLARE recipient record;
BEGIN
 REVOKE ALL ON FUNCTION kaname.authority_metadata_service_account_access_label_ready_v1() FROM PUBLIC;
 FOR recipient IN SELECT DISTINCT r.rolname FROM pg_catalog.pg_proc p
 CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a JOIN pg_catalog.pg_roles r ON r.oid=a.grantee
 WHERE p.oid='kaname.authority_metadata_service_account_access_label_ready_v1()'::regprocedure AND a.grantee<>p.proowner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION kaname.authority_metadata_service_account_access_label_ready_v1() FROM %I',recipient.rolname);
 END LOOP;
 -- Действующие и будущие runtime получают только readiness; DML ACL не расширяется.
 FOR recipient IN SELECT oid FROM pg_catalog.pg_roles
  WHERE kaname._authority_metadata_access_label_runtime_cohort_v2(oid) LOOP
  PERFORM kaname._authority_metadata_access_label_grant_v2(recipient.oid::regrole);
 END LOOP;
 IF NOT kaname._authority_full_contract_storage_v3() OR NOT kaname._authority_access_label_freshness_storage_v1()
  OR NOT kaname.authority_access_label_storage_valid_v1() THEN
  RAISE EXCEPTION 'service account metadata installed closure differs' USING ERRCODE='55000';END IF;
END;
$acl$;
-- +goose StatementEnd

-- +goose Down
SELECT kaname.authority_protocol_drain();
SELECT kaname.authority_protocol_require_owner();
-- +goose StatementBegin
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM kaname.authority_access_label_dirty_root WHERE root_type='iam.serviceAccount') THEN
  RAISE EXCEPTION 'service account access label generations must finish before rollback' USING ERRCODE='55000';END IF;
 IF EXISTS(SELECT 1 FROM kaname.service_accounts WHERE access_labels<>'{}'::jsonb) THEN
  RAISE EXCEPTION 'service account access labels must be cleared through the protected writer before rollback' USING ERRCODE='55000';END IF;
END $$;
-- +goose StatementEnd
DROP TRIGGER access_labels_000_commit_freshness ON kaname.service_accounts;
-- +goose StatementBegin
DO $splice$
DECLARE item record; fn regprocedure; before_body text; after_body text; definition text; pair jsonb;
BEGIN
