 ('authority_metadata_preflight_v4(text,text,boolean,text,jsonb)','2bf3a9aba846a188574bbeb19ac090534236cfa4dd2753be1017991a196be1a2','b10a1b8354ac21f134f7eadd87ee98f61d7e7a13e07d72829ddca80769342352',$pairs$[[" SELECT r.row_xmin,r.row_value INTO STRICT row_xmin,row_value\n FROM kaname._authority_metadata_preflight_body_v4(p_kind,p_id,p_rename,p_audit) r;\n -- Older binaries may keep ordinary edits, but cannot omit the v5 label proof.\n IF p_kind IN ('account','project','service_account') AND p_patch ? 'labels'\n AND p_patch->'labels' IS DISTINCT FROM row_value->'labels' THEN\n  RAISE EXCEPTION 'resource label changes require metadata preflight v5' USING ERRCODE='42501';END IF;\n IF p_rename IS DISTINCT FROM (p_patch ? 'name' AND p_patch->'name' IS DISTINCT FROM row_value->'name') THEN\n  RAISE EXCEPTION 'metadata rename classification changed' USING ERRCODE='40001';END IF;\n next_row:=row_value||p_patch;\n", " SELECT r.row_xmin,r.row_value INTO STRICT row_xmin,row_value\n FROM kaname._authority_metadata_preflight_body_v4(p_kind,p_id,p_rename,p_audit) r;\n -- Older binaries may keep ordinary edits, but cannot omit the v5 label proof.\n IF p_kind IN ('account','project') AND p_patch ? 'labels'\n AND p_patch->'labels' IS DISTINCT FROM row_value->'labels' THEN\n  RAISE EXCEPTION 'account/project label changes require metadata preflight v5' USING ERRCODE='42501';END IF;\n IF p_rename IS DISTINCT FROM (p_patch ? 'name' AND p_patch->'name' IS DISTINCT FROM row_value->'name') THEN\n  RAISE EXCEPTION 'metadata rename classification changed' USING ERRCODE='40001';END IF;\n next_row:=row_value||p_patch;\n"]]$pairs$::jsonb),
 ('authority_protocol_row_guard()','6f7973209b9f2dd87e2734a257d8215054b68a3efd404bb67a2fe59188a0d251','51d8a2759e3576e4356d00784dff001ad8462a3079bacf39f50bcb980cf3a65e',$pairs$[[" -- Owner handoff переживает Close и catalog invalidation: переход в\n -- transition не открывает старому binary raw label UPDATE. Наличие handoff\n -- здесь намеренно не требует совпадения digest с закрытой identity. Legacy\n -- uninitialized без подготовки сохраняется только у account/project;\n -- SA labels требуют signed program также в gen1. FULL сохраняет контракт.\n IF TG_TABLE_SCHEMA='kaname' AND TG_TABLE_NAME IN ('accounts','projects','service_accounts') AND TG_OP='UPDATE' THEN\n  IF to_jsonb(OLD)->'labels' IS DISTINCT FROM to_jsonb(NEW)->'labels'\n  AND (EXISTS(SELECT 1 FROM kaname.authority_writer_contract c CROSS JOIN kaname.authority_semantic_identity a\n   JOIN kaname.authority_bundle_handoff h ON h.singleton=a.singleton\n   WHERE c.singleton AND a.singleton AND c.required_contract=1 AND a.phase<>'uninitialized')\n   OR (TG_TABLE_NAME='service_accounts' AND EXISTS(SELECT 1 FROM kaname.authority_writer_contract c\n    WHERE c.singleton AND c.required_contract=1))) THEN\n   proof:=kaname.authority_protocol_attestation();\n   IF proof IS NULL OR proof->>'writer_contract' IS DISTINCT FROM '1'\n   OR proof->>'kind' IS DISTINCT FROM 'resource' OR proof->>'purpose' IS DISTINCT FROM 'participant'\n", " -- Owner handoff переживает Close и catalog invalidation: переход в\n -- transition не открывает старому binary raw label UPDATE. Наличие handoff\n -- здесь намеренно не требует совпадения digest с закрытой identity. Legacy\n -- uninitialized без подготовки и FULL сохраняют прежние контракты.\n IF TG_TABLE_SCHEMA='kaname' AND TG_TABLE_NAME IN ('accounts','projects') AND TG_OP='UPDATE' THEN\n  IF to_jsonb(OLD)->'labels' IS DISTINCT FROM to_jsonb(NEW)->'labels'\n  AND EXISTS(SELECT 1 FROM kaname.authority_writer_contract c CROSS JOIN kaname.authority_semantic_identity a\n   JOIN kaname.authority_bundle_handoff h ON h.singleton=a.singleton\n   WHERE c.singleton AND a.singleton AND c.required_contract=1 AND a.phase<>'uninitialized') THEN\n   proof:=kaname.authority_protocol_attestation();\n   IF proof IS NULL OR proof->>'writer_contract' IS DISTINCT FROM '1'\n   OR proof->>'kind' IS DISTINCT FROM 'resource' OR proof->>'purpose' IS DISTINCT FROM 'participant'\n"]]$pairs$::jsonb)
 ) changes(signature,before_hash,after_hash,replacements) LOOP
  fn:=to_regprocedure('kaname.'||item.signature);
  SELECT prosrc INTO STRICT before_body FROM pg_catalog.pg_proc WHERE oid=fn
   AND proowner=(SELECT relowner FROM pg_catalog.pg_class WHERE oid='kaname.authority_writer_protocol'::regclass);
  IF encode(sha256(convert_to(before_body,'UTF8')),'hex') IS DISTINCT FROM item.before_hash THEN
   RAISE EXCEPTION 'service account metadata predecessor differs: %',item.signature USING ERRCODE='55000';END IF;
  after_body:=before_body;
  FOR pair IN SELECT value FROM jsonb_array_elements(item.replacements) LOOP
   IF length(pair->>0)=0 OR (length(after_body)-length(replace(after_body,pair->>0,'')))/length(pair->>0)<>1 THEN
    RAISE EXCEPTION 'service account metadata splice is not unique: %',item.signature USING ERRCODE='55000';END IF;
   after_body:=replace(after_body,pair->>0,pair->>1);
  END LOOP;
  IF encode(sha256(convert_to(after_body,'UTF8')),'hex') IS DISTINCT FROM item.after_hash THEN
   RAISE EXCEPTION 'service account metadata result differs: %',item.signature USING ERRCODE='55000';END IF;
  definition:=pg_get_functiondef(fn);
  IF position(before_body IN definition)=0 THEN RAISE EXCEPTION 'installed function body absent' USING ERRCODE='55000';END IF;
  EXECUTE replace(definition,before_body,after_body);
 END LOOP;
END;
$splice$;
-- +goose StatementEnd

DROP FUNCTION kaname.authority_metadata_service_account_access_label_ready_v1();
ALTER TABLE kaname.authority_access_label_dirty_root DROP CONSTRAINT authority_access_label_dirty_root_type;
ALTER TABLE kaname.authority_access_label_dirty_root ADD CONSTRAINT authority_access_label_dirty_root_type
 CHECK(root_type IN ('iam.account','iam.project'));
-- +goose StatementBegin
DO $$ BEGIN
 IF NOT kaname._authority_full_contract_storage_v3() OR NOT kaname._authority_access_label_freshness_storage_v1()
  OR NOT kaname.authority_access_label_storage_valid_v1() THEN
  RAISE EXCEPTION 'service account metadata restored closure differs' USING ERRCODE='55000';END IF;
END $$;
-- +goose StatementEnd
